python3 << 'EOF'
import fitz, numpy as np
d = fitz.open('eprint/plots/ma_fa.pdf')
p = d[0]
draws = p.get_drawings()

def pathpoints(dr):
    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
        elif it[0]=='c':
            for pt in it[1:]:
                pts.append((pt.x,pt.y))
        elif it[0]=='re':
            r=it[1]; pts.append((r.x0,r.y0)); pts.append((r.x1,r.y1))
    # dedupe consecutive
    out=[]
    for pt in pts:
        if not out or abs(pt[0]-out[-1][0])>1e-6 or abs(pt[1]-out[-1][1])>1e-6:
            out.append(pt)
    return out

def toc(x,y):
    logm = -20 + (x-37.8)/14.2625   # per-decade from label spacing (28.525/2)
    logg = -17 - (y-165.7)/15.645
    return logm, logg

for idx,name in [(3,'blue'),(4,'red'),(5,'green')]:
    pts = pathpoints(draws[idx])
    print(f'--- {name} stroke, {len(pts)} pts ---')
    for x,y in pts:
        lm,lg = toc(x,y)
        print(f'{x:7.2f} {y:7.2f}   logm={lm:7.2f} log(1/fa)={lg:7.2f}')
EOF
